"""Turn-scoped memory manager for the engine runtime.

:class:`MemoryManager` is the runtime counterpart to the static schema types
in :mod:`rasa.mantle.memory.schema`. It is bound to a
:class:`~rasa.mantle.state.tracker_handle.TrackerHandle` at construction and
provides typed, schema-scoped reads and writes over tracker slots.

**Slot name resolution precedence:** skill-scoped > project-level > verbatim
fallback. The verbatim fallback is a **read-path** convenience only —
:meth:`MemoryManager.set` rejects an undeclared entry (``MemoryWriteError``)
rather than writing it to a verbatim, un-namespaced slot.

:meth:`MemoryManager.get` additionally accepts **fully-qualified** slot names
(``{skill_id}.{entry}``, ``project.{entry}``) when the first segment is a known
namespace. Those reads are gated by the same readable set as
:meth:`MemoryManager.read_all` (own public+private, other skills' public,
project). Non-readable qualified names return ``None`` and do not use the
verbatim fallback.

:meth:`MemoryManager.set` accepts the same qualified forms for **writable**
fields: ``project.{entry}`` (authoritative project namespace, even when the
active skill has a homonym) and ``{active_skill_id}.{entry}`` (authoritative
skill namespace — it does not fall through to project). Cross-skill and
``system.*`` writes are rejected.

**Slot name format:**

- Skill entry:   ``{skill_id}.{entry_name}``  (e.g. ``transfer_money.amount``)
- Project entry: ``project.{entry_name}``     (e.g. ``project.authenticated``)
- System entry:  ``system.{entry_name}``      (e.g. ``system.language``)
- Unknown:       ``{entry_name}`` verbatim    (bare read path only; DEBUG log emitted)

**Type note:** Tracker slots are untyped in permissive mode (``AnySlot`` /
``AnySlotDict``), so values are stored as-is. The LLM tool schema still
exposes the declared types from
:class:`~rasa.mantle.memory.field.MemoryField`.
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Iterable, Iterator

import structlog

from rasa.dialogue_understanding.stack.frames.mantle_stack_frames import (
    OrderedBlockStackFrame,
    SkillStackFrame,
)
from rasa.mantle.memory.field import (
    DiscoveredFact,
    MemoryEntry,
    MemoryField,
    MemoryItem,
)
from rasa.mantle.memory.schema import ProjectMemorySchema
from rasa.mantle.skills.catalog import target_id_for_frame
from rasa.shared.core.events import create_memory_write_event
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from rasa.dialogue_understanding.stack.frames.flow_stack_frame import (
        UserFlowStackFrame,
    )
    from rasa.mantle.skills.catalog import SkillCatalog
    from rasa.mantle.state.tracker_handle import TrackerHandle

structlogger = structlog.get_logger()

# Reserved memory namespaces. Skill entries resolve to slots named
# ``{skill_id}.{entry_name}``, so no skill may claim either name as its id —
# the project validator rejects such ids using these constants.
PROJECT_NAMESPACE = "project"
SYSTEM_NAMESPACE = "system"

_SYSTEM_PREFIX = f"{SYSTEM_NAMESPACE}."
_PROJECT_PREFIX = f"{PROJECT_NAMESPACE}."

_DISCOVERED_MAX_FACTS = 50
"""Cap on stored discovered facts; oldest are evicted first."""

# Engine-internal system entry: the pending correction's resume point (the frame
# and step the flow was on when the user revised a value). Written/read by
# ``TrackerHandle`` via :meth:`MemoryManager.set_system`/:meth:`get_system`.
CORRECTION_RESUME_ENTRY = "correction_resume_point"

# Engine-internal system entry: global list of undeclared, user-volunteered
# facts. Each list item is a JSON-serialised ``DiscoveredFact``. Capped at
# :data:`_DISCOVERED_MAX_FACTS` (oldest evicted first).
DISCOVERED_FACTS_ENTRY = "__discovered__"

# Engine-internal system entry: a builder tool waiting on user yes/no before
# dispatch (``requires_confirmation`` on ``GatedTool``). Payload shape is owned by
# ``TrackerHandle`` / the confirmation gate in the skill executor.
PENDING_TOOL_CONFIRMATION_ENTRY = "pending_tool_confirmation"

# Engine-internal count of consecutive voice silence timeouts.
SILENCE_TIMEOUT_COUNT_ENTRY = "consecutive_silence_timeouts"

# Engine-internal system entry: per-frame set of skill ``on: activate`` utter
# triggers already emitted (``{frame_id: [response_name, ...]}``).
ACTIVATE_TRIGGERS_FIRED_ENTRY = "verbatim_activate_triggers_fired"

# Engine-internal system entry: per-frame ``when:`` trigger match state
# (``{frame_id: {response_name: matched_bool}}``) updated after each evaluation.
WHEN_TRIGGER_MATCH_STATE_ENTRY = "verbatim_when_trigger_match_state"

# Registry of known system-scoped entry names. The ``system.*`` namespace is
# engine-reserved (never a user-facing memory item — see ``reverse_lookup``).
_SYSTEM_ENTRIES: frozenset[str] = frozenset(
    {
        CORRECTION_RESUME_ENTRY,
        DISCOVERED_FACTS_ENTRY,
        PENDING_TOOL_CONFIRMATION_ENTRY,
        SILENCE_TIMEOUT_COUNT_ENTRY,
        ACTIVATE_TRIGGERS_FIRED_ENTRY,
        WHEN_TRIGGER_MATCH_STATE_ENTRY,
    }
)


def iter_readable_memory_fields(
    skill_catalog: "SkillCatalog",
    project_memory: ProjectMemorySchema,
    observing_skill_id: str,
) -> Iterator[tuple[str, MemoryField]]:
    """Yield ``(slot_name, field)`` pairs readable while *observing_skill_id* is active.

    Shared by :meth:`MemoryManager.read_all`, qualified
    :meth:`MemoryManager.get` lookups, and authoring-time prose validation
    so visibility rules cannot drift. Readable set:

    - the observing skill's own public **and** private fields
    - every **other** skill's **public** fields only
    - project fields
    """
    observing = skill_catalog.skill_by_id(observing_skill_id)
    if observing is not None:
        for name, field in observing.memory.definition.all_fields().items():
            yield f"{observing_skill_id}.{name}", field

    for other_id, other_skill in skill_catalog.skills.items():
        if other_id == observing_skill_id:
            continue
        for name, field in other_skill.memory.definition.public.items():
            yield f"{other_id}.{name}", field

    for name, field in project_memory.fields.items():
        yield f"{_PROJECT_PREFIX}{name}", field


def readable_memory_slot_names(
    skill_catalog: "SkillCatalog",
    project_memory: ProjectMemorySchema,
    observing_skill_id: str,
) -> frozenset[str]:
    """Return qualified slot names readable while *observing_skill_id* is active."""
    return frozenset(
        slot_name
        for slot_name, _field in iter_readable_memory_fields(
            skill_catalog, project_memory, observing_skill_id
        )
    )


def iter_all_memory_fields(
    skill_catalog: "SkillCatalog",
    project_memory: ProjectMemorySchema,
) -> Iterator[tuple[str, MemoryField]]:
    """Yield ``(slot_name, field)`` for every declared field across all skills.

    Unlike :func:`iter_readable_memory_fields`, this ignores the runtime
    visibility rules entirely — every skill's public **and** private fields plus
    all project fields, with no observing skill. It exists for the
    developer-facing inspector payload, which shows the full written state of
    the conversation.
    """
    for skill_id, skill in skill_catalog.skills.items():
        for name, field in skill.memory.definition.all_fields().items():
            yield f"{skill_id}.{name}", field

    for name, field in project_memory.fields.items():
        yield f"{_PROJECT_PREFIX}{name}", field


class MemoryAccessError(RasaException):
    """Base class for memory errors.

    Subclassed by the specific memory failures (e.g. :class:`MemoryWriteError`)
    so callers can handle any memory-related error at once with
    ``except MemoryAccessError``. Named to avoid shadowing the built-in
    :class:`MemoryError`. Authoring-time undeclared-memory problems are reported
    as :class:`~rasa.mantle.validation_finding.ValidationFinding` objects by
    :func:`~rasa.mantle.memory.validation.validate_memory_declarations`, not
    raised as exceptions.
    """


class MemoryWriteError(MemoryAccessError):
    """Raised by :meth:`MemoryManager.set` when a write is rejected.

    Causes:
    - The entry is not declared in the owning skill's or the project's
      ``memory.yml`` (writes must target a declared field).
    - A ``project.*`` field is already set
      (:class:`ProjectMemoryAlreadySetError`).

    Callers (e.g. the executor's ``set_field`` tool handler) should catch this
    and surface the reason to the LLM so it can adjust its next action.
    """


class ProjectMemoryAlreadySetError(MemoryWriteError):
    """Raised when a second write targets an already-set ``project.*`` field."""


class MemoryManager:
    """Manages namespaced memory reads and writes for one engine turn.

    Bound to a :class:`~rasa.mantle.state.tracker_handle.TrackerHandle` at
    construction — no tracker argument is needed on any method.

    Slot name resolution for skill/project entries
    -----------------------------------------------
    1. Matches the active skill's ``SkillMemorySchema`` → ``{skill_id}.{entry_name}``
    2. Matches the ``ProjectMemorySchema`` → ``project.{entry_name}``
    3. Rejects any resolved name that starts with ``system.`` (reserved namespace)
    4. Verbatim fallback — ``{entry_name}`` as-is, with a DEBUG log

    :meth:`get` also accepts fully-qualified names whose first segment is
    ``project``, ``system``, or a known skill id. Those reads use the shared
    readable set (see :func:`iter_readable_memory_fields`) and never fall back
    to verbatim slot access.
    """

    def __init__(
        self,
        skill_catalog: "SkillCatalog",
        project_memory: ProjectMemorySchema,
        handle: "TrackerHandle",
    ) -> None:
        self._skill_catalog = skill_catalog
        self._project_memory = project_memory
        self._handle = handle

    # ------------------------------------------------------------------
    # Scope resolution
    # ------------------------------------------------------------------

    def resolve_scope(
        self, frame: "UserFlowStackFrame | SkillStackFrame | OrderedBlockStackFrame"
    ) -> tuple[str, str]:
        """Return the ``(skill_id, flow_id)`` to scope memory ops for *frame*.

        Skill and ordered-block frames carry ``skill_id``; the compiled flow id
        is derived via
        :func:`~rasa.mantle.skills.catalog.target_id_for_frame` (not stored
        on the frame). Temporary while execution still looks up
        activation targets by compiled id.

        For a ``UserFlowStackFrame``, the stored ``skill_id`` is authoritative
        when set. When it is unset — default-skill frames, historical
        ``"flow"`` frames loaded from persistence, or stacks rewritten by
        correction — the owning skill is resolved from the flow id via
        :meth:`~rasa.mantle.skills.catalog.SkillCatalog.owning_skill_for_target_id`.
        This is the same flow-to-skill mapping the LLM tool-schema builder uses,
        so memory scoping (and the tool registry that shares this skill id) stay
        consistent whether or not the frame carries a skill id. Falls back to
        the flow id when the flow has no catalog skill (default skills are keyed
        by flow id).
        """
        if isinstance(frame, (SkillStackFrame, OrderedBlockStackFrame)):
            return frame.skill_id, target_id_for_frame(frame)

        flow_id = frame.flow_id
        if frame.skill_id:
            return frame.skill_id, flow_id
        owning_skill = self._skill_catalog.owning_skill_for_target_id(flow_id)
        return (owning_skill.id if owning_skill is not None else flow_id), flow_id

    # ------------------------------------------------------------------
    # Skill / project entries
    # ------------------------------------------------------------------

    def resolve(self, skill_id: str, flow_id: str, entry_name: str) -> str:
        """Return the tracker slot name for the given context and entry.

        Args:
            skill_id: ID of the owning skill.
            flow_id: ID of the active flow (reserved for future flow-scoped entries).
            entry_name: Bare field name as declared in ``memory.yml``.

        Returns:
            The fully-qualified tracker slot name.

        Raises:
            ValueError: When the resolved name would collide with the reserved
                ``system.*`` namespace.
        """
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is not None:
            skill_fields = skill.memory.definition.all_fields()
            if entry_name in skill_fields:
                slot_name = f"{skill_id}.{entry_name}"
                _guard_system_namespace(slot_name, entry_name)
                return slot_name

        if entry_name in self._project_memory.fields:
            slot_name = f"{_PROJECT_PREFIX}{entry_name}"
            _guard_system_namespace(slot_name, entry_name)
            return slot_name

        _guard_system_namespace(entry_name, entry_name)
        structlogger.debug(
            "mantle.memory_manager.resolve.fallback",
            entry_name=entry_name,
            skill_id=skill_id,
        )
        return entry_name

    def get(self, skill_id: str, flow_id: str, entry_name: str) -> MemoryEntry | None:
        """Return the field definition and current runtime value, or ``None``.

        When the slot is unset, returns a
        :class:`~rasa.mantle.memory.field.MemoryEntry` with
        ``value=None``.

        *entry_name* may be a bare field name (resolved against the active
        skill, then project, then verbatim) or a fully-qualified slot name
        whose first segment is ``project``, ``system``, or a known skill id.
        Qualified names are readable only when they appear in the same set as
        :meth:`read_all`; otherwise this method returns ``None`` without
        falling back to a verbatim tracker read.

        Args:
            skill_id: ID of the observing (active) skill.
            flow_id: ID of the active flow.
            entry_name: Bare field name as declared in ``memory.yml``, or a
                fully-qualified slot name (``{skill_id}.{entry}`` /
                ``project.{entry}``).

        Returns:
            A :class:`~rasa.mantle.memory.field.MemoryEntry` pairing
            the field definition and current value, or ``None`` when a
            qualified name is not readable.
        """
        if self._is_qualified_slot_name(entry_name):
            return self._get_readable_qualified(skill_id, entry_name)

        slot_name = self.resolve(skill_id, flow_id, entry_name)
        field = self._resolve_field(skill_id, entry_name)

        value = self._handle.get_slot(slot_name)
        return MemoryEntry(
            field=field if field is not None else MemoryField(),
            value=value,
        )

    def set(self, skill_id: str, flow_id: str, entry_name: str, value: Any) -> None:
        """Write a memory field value to the tracker.

        Args:
            skill_id: ID of the owning skill.
            flow_id: ID of the active flow.
            entry_name: Bare field name as declared in ``memory.yml``, or a
                fully-qualified slot name (``project.{entry}`` always writes
                project memory; ``{skill_id}.{entry}`` for the active skill
                writes that skill field only).
            value: Value to write.

        Raises:
            :exc:`MemoryWriteError`: When the entry is not declared in any
                ``memory.yml``, a ``project.*`` field is already set
                (:class:`ProjectMemoryAlreadySetError`), the entry name
                collides with the reserved ``system.*`` namespace, or the
                name is a cross-skill fully-qualified write.
                Writes fail loudly — unlike reads (:meth:`get`), which return
                ``None`` when a name is not readable — so callers can surface
                the reason to the LLM and adjust the next action.
        """
        if self._is_qualified_slot_name(entry_name):
            self._set_qualified(skill_id, entry_name, value)
            return

        try:
            resolved_name = self.resolve(skill_id, flow_id, entry_name)
        except ValueError as exc:
            # resolve() rejects names that collide with the reserved system.*
            # namespace. Surface it as a write failure so callers only ever
            # handle MemoryWriteError on the write path.
            raise MemoryWriteError(str(exc)) from exc

        field = self._resolve_field(skill_id, entry_name)
        if field is None:
            raise MemoryWriteError(
                f"Write to undeclared memory entry {entry_name!r} rejected. "
                "Declare it under the owning skill's or the project's memory.yml "
                "before a tool or step writes it."
            )

        self._reject_if_project_already_set(resolved_name, entry_name)

        self._handle.apply_events([create_memory_write_event(resolved_name, value)])

    def set_named_project_slot_for_button(self, slot_name: str, value: Any) -> None:
        """Write *value* to ``project.{entry}`` for a static button payload.

        The inbound ``set:session.project.*`` button intercept calls this so
        the payload namespace is authoritative. :meth:`set` uses the same
        project-write path for ``project.{entry}`` tool writes.
        """
        if not slot_name.startswith(_PROJECT_PREFIX):
            raise MemoryWriteError(
                f"Button project write requires a project-scoped memory"
                f"entry name; got {slot_name!r}."
            )
        self._set_project_entry(slot_name[len(_PROJECT_PREFIX) :], value)

    def _set_qualified(self, skill_id: str, slot_name: str, value: Any) -> None:
        """Route a fully-qualified write by namespace, or reject it.

        :meth:`set` calls this instead of :meth:`resolve` when
        :meth:`_is_qualified_slot_name` is true, so the prefix is the
        namespace and is not treated as a literal field name.

        ``project.{entry}`` is written via :meth:`_set_project_entry`.
        ``{skill_id}.{entry}`` (the active skill) is written via
        :meth:`_set_skill_entry`. Those helpers check that *entry* is
        declared. ``system.*`` and another skill's prefix raise here
        without a field lookup.

        Args:
            skill_id: Active skill performing the write.
            slot_name: Fully-qualified name (``project.{entry}``,
                ``system.{entry}``, or ``{known_skill_id}.{entry}``).
            value: Value to write when the name is writable.

        Raises:
            MemoryWriteError: When the namespace is ``system``, another
                skill, or the remainder is undeclared in the
                delegated helper. :class:`ProjectMemoryAlreadySetError`
                when a project field is already set.
        """
        namespace, _separator, remainder = slot_name.partition(".")
        if namespace == PROJECT_NAMESPACE:
            self._set_project_entry(remainder, value)
            return
        if namespace == SYSTEM_NAMESPACE:
            raise MemoryWriteError(
                f"Write to reserved system memory entry {slot_name!r} rejected."
            )
        if namespace == skill_id:
            self._set_skill_entry(skill_id, remainder, value)
            return
        raise MemoryWriteError(f"Cross-skill write to {slot_name!r} rejected.")

    def _set_skill_entry(self, skill_id: str, entry_name: str, value: Any) -> None:
        """Write *entry_name* on *skill_id*, bypassing skill-then-project resolve."""
        slot_name = f"{skill_id}.{entry_name}"
        _guard_system_namespace(slot_name, entry_name)
        skill = self._skill_catalog.skill_by_id(skill_id)
        field = (
            skill.memory.definition.all_fields().get(entry_name)
            if skill is not None
            else None
        )
        if field is None:
            raise MemoryWriteError(
                f"Write to undeclared memory entry {slot_name!r} rejected. "
                "Declare it under the owning skill's memory.yml "
                "before a tool or step writes it."
            )
        self._handle.apply_events([create_memory_write_event(slot_name, value)])

    def _set_project_entry(self, entry_name: str, value: Any) -> None:
        """Write *entry_name* in the project namespace, not skill-first resolve."""
        slot_name = f"{_PROJECT_PREFIX}{entry_name}"
        _guard_system_namespace(slot_name, entry_name)
        field = self._project_memory.fields.get(entry_name)
        if field is None:
            raise MemoryWriteError(
                f"Write to undeclared memory entry {slot_name!r} rejected. "
                "Declare it under the owning skill's or the project's memory.yml "
                "before a tool or step writes it."
            )
        self._reject_if_project_already_set(slot_name, entry_name)
        self._handle.apply_events([create_memory_write_event(slot_name, value)])

    def clear_entries(
        self,
        skill_id: str,
        flow_id: str,
        entry_names: Iterable[str],
    ) -> None:
        """Reset declared memory entries to their schema ``initial_value``.

        Each entry is reset via :meth:`set`. When no ``initial_value`` is declared,
        the reset target is ``None``. Write failures are logged and skipped so
        callers can reset a batch without aborting on one invalid field.

        Args:
            skill_id: ID of the owning skill.
            flow_id: ID of the active flow.
            entry_names: Bare field names as declared in ``memory.yml``.
        """
        for entry_name in entry_names:
            field = self._resolve_field(skill_id, entry_name)
            reset_value = field.initial_value if field is not None else None
            try:
                self.set(skill_id, flow_id, entry_name, reset_value)
            except MemoryWriteError:
                structlogger.warning(
                    "mantle.memory_manager.clear_entry_failed",
                    skill_id=skill_id,
                    flow_id=flow_id,
                    entry=entry_name,
                )

    def reset_entries_to_initial(
        self,
        skill_id: str,
        flow_id: str,
        entry_names: Iterable[str],
    ) -> None:
        """Reset skill entries for a new run.

        This is an engine lifecycle operation rather than an authored write.
        Entries already at their schema default are skipped so callers avoid
        redundant memory-write events on the tracker. Use
        :meth:`clear_entries` to reset unconditionally.

        Args:
            skill_id: ID of the owning skill.
            flow_id: ID of the active flow.
            entry_names: Bare field names as declared in ``memory.yml``.
        """
        for entry_name in entry_names:
            field = self._resolve_field(skill_id, entry_name)
            if field is None:
                continue
            slot_name = self.resolve(skill_id, flow_id, entry_name)
            if self._handle.get_slot(slot_name) == field.initial_value:
                continue
            self._handle.apply_events(
                [create_memory_write_event(slot_name, field.initial_value)]
            )

    def read_all(self, skill_id: str, flow_id: str) -> dict[str, MemoryEntry]:
        """Return field definitions and current values for all accessible entries.

        Keyed by fully-qualified slot name (e.g. ``transfer_money.amount``,
        ``project.authenticated``).

        Used for prompt population, setter tool schema generation, and condition
        evaluation (callers extract ``.value`` per entry).

        Readable set while *skill_id* is active:

        - that skill's own public **and** private fields
        - every **other** skill's **public** fields only
        - project fields

        The skill and project namespaces are enumerated separately so name
        collisions between them are handled correctly — a project field named
        ``amount`` always appears under ``project.amount`` even when the active
        skill also declares an ``amount`` field.

        Args:
            skill_id: ID of the observing (active) skill.
            flow_id: ID of the active flow.

        Returns:
            A mapping of slot name →
            :class:`~rasa.mantle.memory.field.MemoryEntry`
            for all readable entries.
        """
        result: dict[str, MemoryEntry] = {}

        for slot_name, field in iter_readable_memory_fields(
            self._skill_catalog, self._project_memory, skill_id
        ):
            # System namespace is reserved; skill ids are validated not to collide.
            entry_name = slot_name.rsplit(".", 1)[-1]
            _guard_system_namespace(slot_name, entry_name)
            result[slot_name] = self._entry_for_slot(slot_name, field)

        return result

    def read_all_for_inspector(self) -> dict[str, MemoryEntry]:
        """Return field definitions and current values for *every* declared entry.

        The unrestricted counterpart to :meth:`read_all`: every skill's public
        and private fields plus all project fields, ignoring visibility. Used
        only by the developer inspector payload, which shows the conversation's
        full written state regardless of which skill is active. Keyed by
        fully-qualified slot name, like :meth:`read_all`.
        """
        return {
            slot_name: self._entry_for_slot(slot_name, field)
            for slot_name, field in iter_all_memory_fields(
                self._skill_catalog, self._project_memory
            )
        }

    def reverse_lookup(self, slot_name: str) -> MemoryItem | None:
        """Return the memory item a fully-qualified *slot_name* maps back to.

        The inverse of :meth:`resolve`: turns a tracker slot name (as carried on
        a memory-write event or in write-provenance) back into the owning scope,
        bare entry name, and field declaration, so callers reason in memory items
        rather than parsing slot strings.

        Resolution mirrors the slot-name format, by prefix:

        - ``system.{entry}`` → ``None``. The ``system.*`` namespace is
          engine-reserved and never user-correctable.
        - ``project.{entry}`` → project scope (``skill_id=None``); field from
          the project schema, or a bare :class:`MemoryField` when undeclared.
        - ``{skill_id}.{entry}`` → skill scope when ``skill_id`` is a known
          skill; field from the skill schema, or a bare :class:`MemoryField`
          when the entry is not declared on that skill.
        - anything else (no separator, or an unknown skill prefix) → verbatim
          fallback: the whole name is the entry and the field is unknown.

        Only the **first** separator is split, so multi-segment entry names
        (e.g. ``project.address.city``) survive intact.

        Args:
            slot_name: Fully-qualified tracker slot name.

        Returns:
            A :class:`~rasa.mantle.memory.field.MemoryItem`, or ``None``
            for the reserved ``system.*`` namespace.
        """
        if slot_name.startswith(_SYSTEM_PREFIX):
            return None

        if slot_name.startswith(_PROJECT_PREFIX):
            entry_name = slot_name[len(_PROJECT_PREFIX) :]
            field = self._project_memory.fields.get(entry_name) or MemoryField()
            return MemoryItem(skill_id=None, entry_name=entry_name, field=field)

        skill_id, separator, entry_name = slot_name.partition(".")
        if separator:
            skill = self._skill_catalog.skill_by_id(skill_id)
            if skill is not None:
                field = skill.memory.definition.all_fields().get(entry_name) or (
                    MemoryField()
                )
                return MemoryItem(
                    skill_id=skill_id,
                    entry_name=entry_name,
                    field=field,
                )

        return MemoryItem(skill_id=None, entry_name=slot_name, field=MemoryField())

    # ------------------------------------------------------------------
    # System entries
    # ------------------------------------------------------------------

    def get_system(self, entry_name: str) -> Any:
        """Return the current value of a system-scoped memory entry.

        Always reads from the ``system.{entry_name}`` tracker slot, not
        skill- or project-scoped memory.

        Args:
            entry_name: Name of the system entry (must be in the registry).

        Returns:
            The current slot value, or ``None`` if unset.

        Raises:
            KeyError: When *entry_name* is not a known system entry.
        """
        _require_known_system_entry(entry_name)
        slot_name = f"{_SYSTEM_PREFIX}{entry_name}"
        return self._handle.get_slot(slot_name)

    def set_system(self, entry_name: str, value: Any) -> None:
        """Write a system-scoped memory entry.

        Always writes to the ``system.{entry_name}`` tracker slot, not
        skill- or project-scoped memory.

        Args:
            entry_name: Name of the system entry (must be in the registry).
            value: Value to write.

        Raises:
            KeyError: When *entry_name* is not a known system entry.
        """
        _require_known_system_entry(entry_name)
        slot_name = f"{_SYSTEM_PREFIX}{entry_name}"
        self._handle.apply_events([create_memory_write_event(slot_name, value)])

    # ------------------------------------------------------------------
    # Discovered memory (undeclared facts)
    # ------------------------------------------------------------------

    def add_discovered_fact(self, fact: DiscoveredFact) -> None:
        """Append or replace *fact* in the global discovered-facts system sidecar.

        When a fact with the same ``key`` already exists, the stored entry is
        refreshed and moved to the end so rediscovery keeps it from cap
        eviction on the next append. New keys are appended; evicts the oldest
        entries once the list exceeds :data:`_DISCOVERED_MAX_FACTS`.
        """
        raw = _read_discovered_facts_list(self)
        serialized = fact.model_dump(mode="json")
        action = "replaced"
        evicted_count = 0
        for index, item in enumerate(raw):
            if isinstance(item, dict) and item.get("key") == fact.key:
                raw.pop(index)
                raw.append(serialized)
                break
        else:
            action = "appended"
            raw.append(serialized)
            if len(raw) > _DISCOVERED_MAX_FACTS:
                evicted_count = len(raw) - _DISCOVERED_MAX_FACTS
                raw = raw[-_DISCOVERED_MAX_FACTS:]
        self.set_system(DISCOVERED_FACTS_ENTRY, raw)
        structlogger.debug(
            "mantle.memory_manager.discovered_fact.stored",
            fact_key=fact.key,
            action=action,
            stored_count=len(raw),
            evicted_count=evicted_count,
            mapping_count=len(fact.potential_mappings),
            pii=fact.pii,
            captured_by_skill=fact.captured_by_skill,
        )

    def get_discovered_facts(self) -> list[DiscoveredFact]:
        """Return every stored :class:`DiscoveredFact`, oldest first.

        Global read with no per-skill partition. Malformed entries (e.g. from
        an older build) are skipped with a warning rather than failing the
        whole read.
        """
        raw = _read_discovered_facts_list(self)
        facts: list[DiscoveredFact] = []
        for item in raw:
            try:
                facts.append(DiscoveredFact.model_validate(item))
            except Exception:
                structlogger.warning(
                    "mantle.memory_manager.get_discovered_facts.invalid_entry",
                    entry_type=type(item).__name__,
                )
        return facts

    # ------------------------------------------------------------------
    # Private helpers
    # ------------------------------------------------------------------

    def _reject_if_project_already_set(
        self, resolved_name: str, entry_name: str
    ) -> None:
        """Raise when a ``project.*`` slot already has a non-``None`` value."""
        if not resolved_name.startswith(_PROJECT_PREFIX):
            return
        current = self._handle.get_slot(resolved_name)
        if current is not None:
            raise ProjectMemoryAlreadySetError(
                f"Project memory field {entry_name!r} is already set and "
                "cannot be overwritten."
            )

    def _resolve_field(self, skill_id: str, field_name: str) -> MemoryField | None:
        """Return the field definition for *field_name*, or ``None``.

        Looks up the :class:`~rasa.mantle.memory.field.MemoryField` in the
        skill schema first, then the project schema.
        """
        skill = self._skill_catalog.skill_by_id(skill_id)
        if skill is not None:
            skill_fields = skill.memory.definition.all_fields()
            if field_name in skill_fields:
                return skill_fields[field_name]

        return self._project_memory.fields.get(field_name)

    @property
    def project_memory(self) -> ProjectMemorySchema:
        """Project-wide memory schema (``project.*`` slots)."""
        return self._project_memory

    def button_writable_memory_keys(self, skill_id: str | None) -> frozenset[str]:
        """Return memory keys a button from *skill_id* may write.

        Same set named-response buttons use: every field on that skill, plus
        every project field. An unknown skill id yields no keys. ``None``
        yields project fields only.

        Args:
            skill_id: Skill that owns the tool sending the button, or ``None``
                when the tool has no skill scope.

        Returns:
            Fully-qualified memory keys (``{skill_id}.{entry}`` and
            ``project.{entry}``).
        """
        from rasa.mantle.content.static_buttons import (
            button_writable_memory_keys_for_skill,
        )

        return button_writable_memory_keys_for_skill(
            self._skill_catalog,
            self._project_memory,
            skill_id,
        )

    def _is_qualified_slot_name(self, entry_name: str) -> bool:
        """Return whether *entry_name* is a fully-qualified memory slot name.

        Qualified names use the same first-segment rule as
        :meth:`reverse_lookup`: ``project.*``, ``system.*``, or
        ``{known_skill_id}.*``. Multi-segment bare entry names (e.g.
        ``address.city``) are not treated as qualified unless the first
        segment is one of those namespaces.
        """
        namespace, separator, _remainder = entry_name.partition(".")
        if not separator:
            return False
        if namespace in (PROJECT_NAMESPACE, SYSTEM_NAMESPACE):
            return True
        return self._skill_catalog.skill_by_id(namespace) is not None

    def _get_readable_qualified(
        self, observing_skill_id: str, slot_name: str
    ) -> MemoryEntry | None:
        """Return a readable fully-qualified slot, or ``None`` when inaccessible.

        Looks up *slot_name* in the same readable set as :meth:`read_all`
        (:func:`iter_readable_memory_fields`). Does not fall back to verbatim
        tracker reads.
        """
        field = self._readable_field(observing_skill_id, slot_name)
        if field is None:
            return None
        return self._entry_for_slot(slot_name, field)

    def _readable_field(
        self, observing_skill_id: str, slot_name: str
    ) -> MemoryField | None:
        """Return the field for *slot_name* if it is readable while observing."""
        for readable_slot, field in iter_readable_memory_fields(
            self._skill_catalog, self._project_memory, observing_skill_id
        ):
            if readable_slot == slot_name:
                return field
        return None

    def _entry_for_slot(self, slot_name: str, field: MemoryField) -> MemoryEntry:
        """Pair *field* with the current tracker value for *slot_name*."""
        return MemoryEntry(field=field, value=self._handle.get_slot(slot_name))


# ---------------------------------------------------------------------------
# Module-level helpers
# ---------------------------------------------------------------------------


def _read_discovered_facts_list(manager: "MemoryManager") -> list[Any]:
    """Return the discovered-facts list, or ``[]`` when unset or corrupt."""
    raw = manager.get_system(DISCOVERED_FACTS_ENTRY)
    if raw is None:
        return []
    if not isinstance(raw, list):
        structlogger.warning(
            "mantle.memory_manager.discovered_facts.invalid_type",
            slot_type=type(raw).__name__,
        )
        return []
    return list(raw)


def _guard_system_namespace(slot_name: str, entry_name: str) -> None:
    """Raise :exc:`ValueError` when *slot_name* collides with the system namespace.

    Args:
        slot_name: Resolved fully-qualified slot name.
        entry_name: Original bare entry name (used in the error message).

    Raises:
        ValueError: When *slot_name* starts with ``system.``.
    """
    if slot_name.startswith(_SYSTEM_PREFIX):
        raise ValueError(
            f"Memory entry {entry_name!r} resolves to {slot_name!r} which "
            "collides with the reserved 'system.*' namespace. "
            "Rename the entry or the skill to avoid this collision."
        )


def _require_known_system_entry(entry_name: str) -> None:
    """Raise :exc:`KeyError` when *entry_name* is not a registered system entry.

    Args:
        entry_name: System entry name to validate.

    Raises:
        KeyError: When *entry_name* is not in :data:`_SYSTEM_ENTRIES`.
    """
    if entry_name not in _SYSTEM_ENTRIES:
        raise KeyError(
            f"Unknown system memory entry {entry_name!r}. "
            f"Known entries: {sorted(_SYSTEM_ENTRIES) or '(none registered yet)'}"
        )
